-- UK Transport & Smart Mobility Challenge — UK-wide schema
-- Covers England (London + 8 regions), Scotland, Wales, Northern Ireland.
-- Load order: dim_areas -> dim_routes -> fact_journeys / ev_charge_points

CREATE TABLE dim_areas (
    area_id                 INT PRIMARY KEY,
    area_name               VARCHAR(50) NOT NULL,
    nation                  VARCHAR(20) NOT NULL,   -- England / Scotland / Wales / Northern Ireland
    region                  VARCHAR(30) NOT NULL,   -- London, South East, Scotland, Wales, ...
    population              INT,
    area_km2                DECIMAL(6,1),
    avg_household_income_gbp INT
);

CREATE TABLE dim_routes (
    route_id          INT PRIMARY KEY,
    route_name        VARCHAR(70) NOT NULL,
    mode              VARCHAR(10) NOT NULL,        -- Bus / Rail / Tube / Tram / Metro
    operator          VARCHAR(60),
    area_id           INT REFERENCES dim_areas(area_id),
    route_length_km   DECIMAL(5,1)
);

CREATE TABLE fact_journeys (
    journey_id            INT PRIMARY KEY,
    route_id              INT REFERENCES dim_routes(route_id),
    journey_date          DATE NOT NULL,
    day_of_week           VARCHAR(10),
    scheduled_departure   VARCHAR(5),
    actual_departure      VARCHAR(5),
    delay_minutes         DECIMAL(5,1),
    passengers_boarded    INT,
    weather_condition     VARCHAR(10)
);

CREATE TABLE ev_charge_points (
    charge_point_id     INT PRIMARY KEY,
    area_id             INT REFERENCES dim_areas(area_id),
    location_name       VARCHAR(80),
    latitude            DECIMAL(8,5),
    longitude           DECIMAL(8,5),
    connector_count     INT,
    charge_speed_type   VARCHAR(15),
    installed_date      DATE,
    status              VARCHAR(20),
    operator            VARCHAR(30)
);


